/*verilator coverage_off*/
// USB3 link + protocol layer: a cycle-level model fed only by the pins
// predicts tx_p, link_up and irq on every clock. The receiver is modelled as
// a packet collector (header bytes, 64-byte payload, CRC, END) judged when
// the framing is complete; the transmitter as a list of packet symbols
// generated by index (TP: 5 symbols, DPH+DPP: 74 symbols) after one idle
// decision clock, with the IN payload read from a shadow of the bulk buffer.
`include "cov_macros.svh"
module USB3_sva (
  input logic       clk, rst_n, link_up, irq,
  input logic [7:0] rx_p, rx_n, tx_p, tx_n,
  input logic       await_ack, in_active
);
  `COV_CLOCKING(clk, !rst_n)

  localparam logic [7:0] IDLE = 8'h00, LFPS = 8'hAA, DPH = 8'hBC, TPS = 8'h4B,
                         DPP = 8'h5A, ENDS = 8'h3C;
  localparam logic [3:0] ACK = 4'hA, NRDY = 4'h5, LBAD = 4'hB;
  localparam int TK_LFPS = 0, TK_IDLE = 1, TK_TP = 2, TK_DP = 3;

  function automatic logic [4:0] crc5(input logic [15:0] d);
    logic [4:0] c;
    c = 5'h1F;
    for (int i = 0; i < 16; i++) c = {d[i] ^ c[0], c[4], c[3] ^ d[i] ^ c[0], c[2], c[1]};
    crc5 = ~c;
  endfunction
  function automatic logic [31:0] crc32(input logic [31:0] c, input logic [7:0] d);
    for (int i = 0; i < 8; i++) c = (c >> 1) ^ ((d[i] ^ c[0]) ? 32'hEDB8_8320 : 32'h0);
    crc32 = c;
  endfunction

  wire ok   = rx_n == ~rx_p;
  wire lfps = ok && rx_p == LFPS;

  // ---------------- link
  int   lk, dc, bl, rb, wc;
  logic m_lu, warm;
  // ---------------- receiver
  int          rk, rn;
  logic [7:0]  h1, h2;
  logic [31:0] pcrc, rcrc;
  logic [31:0] stage [0:15];
  logic [31:0] mem [0:63];
  logic [3:0]  vblk;
  logic [2:0]  rx_exp, tx_seq;
  logic        m_irq;
  // response slot / IN transfer
  logic        rsp, rsp_rt;
  logic [3:0]  rsp_ty;
  logic [2:0]  rsp_sq;
  logic [1:0]  rsp_bk;
  logic        inp, act, aw, rs;
  logic [1:0]  in_bk, retry;
  int          tmr;
  // ---------------- transmitter
  int          tk, ti, lph, tb;
  logic [7:0]  m_tx;
  logic [3:0]  t_ty;
  logic [2:0]  t_sq;
  logic        t_rt;
  logic [1:0]  t_bk;
  logic [31:0] tcrc;
  logic        p_rsp, p_in, p_rs, p_sent;     // TX -> RX handshake pulses

  // coverage events
  logic v_short, v_sat, v_rxdet_lfps, v_bad_lfps, v_u0, v_warm, v_warm_abort, v_aa_in_pkt,
        v_dec_err, v_bad_idle, v_early_pkt, v_dph_crc, v_unsup, v_no_dpp, v_dpp_end, v_lbad,
        v_inorder, v_dup, v_ooo, v_tp_crc, v_tp_end, v_in_ok, v_in_unwr, v_in_busy, v_ack_done,
        v_ack_seq, v_ack_idle, v_lbad_rs, v_lbad_idle, v_other_tp, v_timeout, v_giveup,
        v_rsp_busy, v_rsp_first, v_rx_wrap, v_tx_wrap, v_warm_in, v_warm_tx, v_hdr_hi,
        v_resend_dp;

  // registered copies for the covergroup: OUT packet outcome x bank and
  // its SEQ, IN request outcome x bank, response TP sent, attempts before
  // an IN transfer is acknowledged
  logic       c_ov, c_iv, c_tv, c_av;
  logic [1:0] c_ok, c_obk, c_ik, c_ibk, c_ar;
  logic [2:0] c_osq;
  logic [3:0] c_tty;
  logic       c_trt;

  function automatic logic [7:0] tp_sym(input int i);
    logic [7:0] s1, s2;
    s1 = {4'h0, t_ty};
    s2 = {t_sq, t_rt, t_bk, 2'b00};
    case (i)
      0: tp_sym = TPS;
      1: tp_sym = s1;
      2: tp_sym = s2;
      3: tp_sym = {3'b000, crc5({s2, s1})};
      default: tp_sym = ENDS;
    endcase
  endfunction
  function automatic logic [7:0] pay(input int i);
    logic [31:0] w;
    w = mem[{in_bk, 4'(i / 4)}];
    pay = w[8 * (i % 4) +: 8];
  endfunction

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      lk <= 0; dc <= 0; bl <= 0; rb <= 0; wc <= 0; m_lu <= 0; warm <= 0;
    end else begin
      warm <= 0;
      {v_short, v_sat, v_rxdet_lfps, v_bad_lfps, v_u0, v_warm, v_warm_abort} <= '0;
      case (lk)
        0: begin
          dc <= (dc + 1) % 32;
          if (dc == 31) begin lk <= 1; bl <= 0; rb <= 0; end
          v_rxdet_lfps <= lfps;
        end
        1: begin
          if (lfps) begin
            bl <= (bl == 8) ? 8 : bl + 1;
            v_sat <= bl == 8;
          end else begin
            if (bl == 8 && rb < 2) rb <= rb + 1;
            v_short <= bl > 0 && bl < 8;
            bl <= 0;
          end
          v_bad_lfps <= !ok && rx_p == LFPS;
          if (rb == 2 && tb == 2) begin lk <= 2; m_lu <= 1; wc <= 0; v_u0 <= 1; end
        end
        default: begin
          if (lfps && rk == 0) begin
            wc <= (wc + 1) % 32;
            if (wc == 31) begin lk <= 0; m_lu <= 0; warm <= 1; v_warm <= 1; end
          end else begin
            v_warm_abort <= wc > 4;
            wc <= 0;
          end
        end
      endcase
    end
  end

  // packet judge (receiver)
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      rk <= 0; rn <= 0; vblk <= 0; rx_exp <= 0; tx_seq <= 0; m_irq <= 0;
      rsp <= 0; rsp_ty <= ACK; rsp_sq <= 0; rsp_rt <= 0; rsp_bk <= 0;
      inp <= 0; act <= 0; aw <= 0; rs <= 0; in_bk <= 0; retry <= 0; tmr <= 0;
      h1 <= 0; h2 <= 0; pcrc <= 0; rcrc <= 0;
      {c_ov, c_iv, c_av} <= '0; c_ok <= 0; c_obk <= 0; c_ik <= 0; c_ibk <= 0; c_ar <= 0; c_osq <= 0;
    end else begin
      {c_ov, c_iv, c_av} <= '0;
      {v_aa_in_pkt, v_dec_err, v_bad_idle, v_early_pkt, v_dph_crc, v_unsup, v_no_dpp, v_dpp_end,
       v_lbad, v_inorder, v_dup, v_ooo, v_tp_crc, v_tp_end, v_in_ok, v_in_unwr, v_in_busy,
       v_ack_done, v_ack_seq, v_ack_idle, v_lbad_rs, v_lbad_idle, v_other_tp, v_timeout,
       v_giveup, v_rx_wrap, v_tx_wrap, v_warm_in, v_hdr_hi} <= '0;
      // transmitter handshakes
      if (p_rsp) rsp <= 0;
      if (p_in) begin inp <= 0; act <= 1; retry <= 0; end
      if (p_rs) begin
        rs <= 0;
        if (retry == 3) begin act <= 0; m_irq <= 1; v_giveup <= 1; end
        else retry <= retry + 1;
      end
      if (p_sent && act) begin aw <= 1; tmr <= 0; end
      else if (aw) begin
        tmr <= tmr + 1;
        if (tmr == 255) begin aw <= 0; rs <= 1; v_timeout <= 1; end
      end
      // collector
      v_aa_in_pkt <= rk != 0 && lfps;
      if (rk != 0 && !ok) begin
        rk <= 0; m_irq <= 1; v_dec_err <= 1;
      end else if (rk == 0) begin
        v_bad_idle  <= !ok;
        v_early_pkt <= lk != 2 && ok && (rx_p == DPH || rx_p == TPS);
        if (lk == 2 && ok && rx_p == DPH) begin rk <= 1; rn <= 0; end
        if (lk == 2 && ok && rx_p == TPS) begin rk <= 2; rn <= 0; end
      end else begin
        rn <= rn + 1;
        if (rn == 0) h1 <= rx_p;
        if (rn == 1) h2 <= rx_p;
        if (rn == 2) v_hdr_hi <= h1[7:4] != 0;
        if (rn == 2 && rx_p != {3'b000, crc5({h2, h1})}) begin
          rk <= 0; m_irq <= 1;
          if (rk == 1) v_dph_crc <= 1; else v_tp_crc <= 1;
        end else if (rk == 1) begin
          // data packet: header CRC ok at rn 2, DPP start at 3, payload 4..67,
          // CRC 68..71, END 72
          if (rn == 2 && h1[3:0] != 4'h1) begin rk <= 0; v_unsup <= 1; end
          if (rn == 3) begin
            pcrc <= 32'hFFFF_FFFF;
            if (rx_p != DPP) begin rk <= 0; m_irq <= 1; v_no_dpp <= 1; end
          end
          if (rn >= 4 && rn < 68) begin
            pcrc <= crc32(pcrc, rx_p);
            stage[(rn - 4) / 4][8 * ((rn - 4) % 4) +: 8] <= rx_p;
          end
          if (rn >= 68 && rn < 72) rcrc[8 * (rn - 68) +: 8] <= rx_p;
          if (rn == 72) begin
            rk <= 0;
            if (rx_p != ENDS) begin m_irq <= 1; v_dpp_end <= 1; end
            else begin
              rsp <= 1; rsp_sq <= h2[7:5]; rsp_bk <= h2[4:3]; rsp_rt <= 0; rsp_ty <= ACK;
              c_ov <= 1; c_obk <= h2[4:3]; c_osq <= h2[7:5];
              c_ok <= rcrc != ~pcrc ? 3 : (h2[7:5] == rx_exp ? 0 : (h2[7:5] == rx_exp - 3'd1 ? 1 : 2));
              if (rcrc != ~pcrc) begin rsp_ty <= LBAD; m_irq <= 1; v_lbad <= 1; end
              else if (h2[7:5] == rx_exp) begin
                for (int k = 0; k < 16; k++) mem[{h2[4:3], 4'(k)}] <= stage[k];
                vblk[h2[4:3]] <= 1;
                rx_exp <= rx_exp + 1;
                v_inorder <= 1; v_rx_wrap <= rx_exp == 7;
              end else if (h2[7:5] == rx_exp - 3'd1) begin
                rsp_rt <= 1; v_dup <= 1;
              end else begin
                rsp_ty <= NRDY; m_irq <= 1; v_ooo <= 1;
              end
            end
          end
        end else if (rn == 3) begin
          // transaction packet END
          rk <= 0;
          if (rx_p != ENDS) begin m_irq <= 1; v_tp_end <= 1; end
          else if (h1[3:0] == ACK && h2[1]) begin
            c_iv <= 1; c_ibk <= h2[3:2]; c_ik <= vblk[h2[3:2]] && !act && !inp ? 0 : (vblk[h2[3:2]] ? 2 : 1);
            if (vblk[h2[3:2]] && !act && !inp) begin
              inp <= 1; in_bk <= h2[3:2]; v_in_ok <= 1;
            end else begin
              rsp <= 1; rsp_ty <= NRDY; rsp_sq <= h2[7:5]; rsp_rt <= 0; rsp_bk <= h2[3:2];
              if (vblk[h2[3:2]]) v_in_busy <= 1; else v_in_unwr <= 1;
            end
          end else if (h1[3:0] == ACK) begin
            if (aw && h2[7:5] == tx_seq) begin
              aw <= 0; act <= 0; tx_seq <= tx_seq + 1; v_ack_done <= 1; v_tx_wrap <= tx_seq == 7;
              c_av <= 1; c_ar <= retry;
            end else if (aw) v_ack_seq <= 1;
            else v_ack_idle <= 1;
          end else if (h1[3:0] == LBAD) begin
            if (aw) begin aw <= 0; rs <= 1; v_lbad_rs <= 1; end
            else v_lbad_idle <= 1;
          end else v_other_tp <= 1;
        end
      end
      if (warm) begin
        rx_exp <= 0; tx_seq <= 0; inp <= 0; act <= 0; aw <= 0; rs <= 0; rsp <= 0;
        v_warm_in <= act;
      end
    end
  end

  // transmitter
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      tk <= TK_LFPS; ti <= 0; lph <= 0; tb <= 0; m_tx <= IDLE;
      t_ty <= ACK; t_sq <= 0; t_rt <= 0; t_bk <= 0; tcrc <= 0;
      p_rsp <= 0; p_in <= 0; p_rs <= 0; p_sent <= 0;
      c_tv <= 0; c_tty <= 0; c_trt <= 0;
    end else begin
      p_rsp <= 0; p_in <= 0; p_rs <= 0; p_sent <= 0;
      c_tv <= 0;
      {v_rsp_busy, v_rsp_first, v_warm_tx, v_resend_dp} <= '0;
      v_rsp_busy <= rsp && tk == TK_DP;
      if (warm) begin
        tk <= TK_LFPS; m_tx <= IDLE; lph <= 0; tb <= 0; v_warm_tx <= tk == TK_DP;
      end else case (tk)
        TK_LFPS: begin
          m_tx <= IDLE;
          if (m_lu) tk <= TK_IDLE;
          else if (lk == 1) begin
            if (lph < 16) m_tx <= LFPS;
            lph <= (lph + 1) % 32;
            if (lph == 15 && tb < 2) tb <= tb + 1;
          end
        end
        TK_IDLE: begin
          m_tx <= IDLE;
          ti <= 0;
          if (rsp) begin
            t_ty <= rsp_ty; t_sq <= rsp_sq; t_rt <= rsp_rt; t_bk <= rsp_bk;
            p_rsp <= 1; tk <= TK_TP;
            c_tv <= 1; c_tty <= rsp_ty; c_trt <= rsp_rt;
            v_rsp_first <= inp || rs;
          end else if (inp || rs) begin
            p_in <= inp; p_rs <= !inp;
            if (inp || retry != 3) tk <= TK_DP;
            v_resend_dp <= !inp && retry != 3;
          end
        end
        TK_TP: begin
          m_tx <= tp_sym(ti);
          ti <= ti + 1;
          if (ti == 4) tk <= TK_IDLE;
        end
        default: begin                               // DPH + DPP
          ti <= ti + 1;
          case (ti)
            0: m_tx <= DPH;
            1: m_tx <= 8'h01;
            2: m_tx <= {tx_seq, in_bk, 3'b000};
            3: m_tx <= {3'b000, crc5({tx_seq, in_bk, 3'b000, 8'h01})};
            4: begin m_tx <= DPP; tcrc <= 32'hFFFF_FFFF; end
            73: begin m_tx <= ENDS; p_sent <= 1; tk <= TK_IDLE; end
            default:
              if (ti < 69) begin
                m_tx <= pay(ti - 5);
                tcrc <= crc32(tcrc, pay(ti - 5));
              end else m_tx <= ~tcrc[8 * (ti - 69) +: 8];
          endcase
        end
      endcase
    end
  end

  `SVA_RST(a_reset_outputs, !rst_n, tx_p == IDLE && !link_up && !irq)
  `SVA_INV(a_tx, tx_p == m_tx)
  `SVA_INV(a_tx_n, tx_n == ~tx_p)
  `SVA_INV(a_link_up, link_up == m_lu)
  `SVA_INV(a_irq, irq == m_irq)
  `SVA_IMP(a_training_symbols, !link_up && !$past(link_up), tx_p == IDLE || tx_p == LFPS)
  `SVA_IMP(a_watchdog_in_transfer, await_ack, in_active)
  `SVA_IMP(a_irq_sticky, irq, ##1 irq)

  covergroup cg_usb3 @(negedge clk);
    option.per_instance = 1;
    cp_out: coverpoint c_ok iff (rst_n && c_ov) { bins in_order = {0}; bins duplicate = {1}; bins out_of_order = {2}; bins bad_crc = {3}; }
    cp_obk: coverpoint c_obk iff (rst_n && c_ov) { bins b[] = {[0:3]}; }
    x_out_bank: cross cp_out, cp_obk;
    cp_osq: coverpoint c_osq iff (rst_n && c_ov && c_ok == 0) { bins s[] = {[0:7]}; }
    cp_in: coverpoint c_ik iff (rst_n && c_iv) { bins accepted = {0}; bins unwritten = {1}; bins busy = {2}; }
    cp_ibk: coverpoint c_ibk iff (rst_n && c_iv) { bins b[] = {[0:3]}; }
    x_in_bank: cross cp_in, cp_ibk;
    cp_tp: coverpoint {c_tty, c_trt} iff (rst_n && c_tv)
      { bins ack = {{ACK, 1'b0}}; bins ack_retry = {{ACK, 1'b1}}; bins nrdy = {{NRDY, 1'b0}}; bins lbad = {{LBAD, 1'b0}}; }
    cp_attempts: coverpoint c_ar iff (rst_n && c_av) { bins first = {0}; bins second = {1}; bins third = {2}; bins fourth = {3}; }
  endgroup
  cg_usb3 u_cg_usb3 = new;

  `FC(rx_lfps_during_rxdet, v_rxdet_lfps)
  `FC(rx_lfps_burst_too_short, v_short)
  `FC(rx_lfps_burst_long, v_sat)
  `FC(rx_lfps_invalid_symbol, v_bad_lfps)
  `FC(link_up, v_u0)
  `FC(warm_reset, v_warm)
  `FC(warm_reset_lfps_interrupted, v_warm_abort)
  `FC(lfps_symbol_inside_packet, v_aa_in_pkt)
  `FC(warm_reset_during_in_transfer, v_warm_in)
  `FC(warm_reset_during_dpp_transmit, v_warm_tx)
  `FC(decode_error_in_packet, v_dec_err)
  `FC(invalid_symbol_between_packets, v_bad_idle)
  `FC(packet_before_u0_ignored, v_early_pkt)
  `FC(header_reserved_bits_set, v_hdr_hi)
  `FC(dph_bad_crc5, v_dph_crc)
  `FC(dph_unsupported_type, v_unsup)
  `FC(dpp_start_missing, v_no_dpp)
  `FC(dpp_bad_end, v_dpp_end)
  `FC(dpp_bad_crc32_lbad, v_lbad)
  `FC(out_in_order_ack, v_inorder)
  `FC(out_duplicate_retry_ack, v_dup)
  `FC(out_out_of_order_nrdy, v_ooo)
  `FC(out_seq_wrap, v_rx_wrap)
  `FC(tp_bad_crc5, v_tp_crc)
  `FC(tp_bad_end, v_tp_end)
  `FC(in_request_accepted, v_in_ok)
  `FC(in_request_unwritten_nrdy, v_in_unwr)
  `FC(in_request_busy_nrdy, v_in_busy)
  `FC(host_ack_completes_in, v_ack_done)
  `FC(in_seq_wrap, v_tx_wrap)
  `FC(host_ack_wrong_seq_ignored, v_ack_seq)
  `FC(host_ack_without_transfer, v_ack_idle)
  `FC(host_lbad_retransmit, v_lbad_rs)
  `FC(host_lbad_without_transfer, v_lbad_idle)
  `FC(host_other_tp_ignored, v_other_tp)
  `FC(ack_timeout_retransmit, v_timeout)
  `FC(retransmit_dpp, v_resend_dp)
  `FC(give_up_after_four_attempts, v_giveup)
  `FC(response_waits_for_dpp, v_rsp_busy)
  `FC(response_before_in_data, v_rsp_first)
  `FC_RST(reset_in_u0, rst_n && link_up ##1 !rst_n)
endmodule

bind USB3_top USB3_sva u_sva (.clk, .rst_n, .link_up, .irq, .rx_p, .rx_n, .tx_p, .tx_n,
                              .await_ack, .in_active);
